const fs = require('fs');
const path = require('path');

const dir = path.join(__dirname, 'src/assets/i18n');
const keys = {
  fr: {
    PHONE_TILT_SCALE: '0° plat · 90° vertical',
    PHONE_TILT_FLAT: 'Téléphone à plat (horizontal)',
    PHONE_TILT_VERTICAL: 'Téléphone vertical'
  },
  en: {
    PHONE_TILT_SCALE: '0° flat · 90° upright',
    PHONE_TILT_FLAT: 'Phone flat (horizontal)',
    PHONE_TILT_VERTICAL: 'Phone upright (vertical)'
  },
  de: {
    PHONE_TILT_SCALE: '0° flach · 90° senkrecht',
    PHONE_TILT_FLAT: 'Telefon flach (horizontal)',
    PHONE_TILT_VERTICAL: 'Telefon senkrecht'
  },
  es: {
    PHONE_TILT_SCALE: '0° plano · 90° vertical',
    PHONE_TILT_FLAT: 'Teléfono plano (horizontal)',
    PHONE_TILT_VERTICAL: 'Teléfono vertical'
  },
  it: {
    PHONE_TILT_SCALE: '0° piatto · 90° verticale',
    PHONE_TILT_FLAT: 'Telefono piatto (orizzontale)',
    PHONE_TILT_VERTICAL: 'Telefono verticale'
  },
  ru: {
    PHONE_TILT_SCALE: '0° плоско · 90° вертикально',
    PHONE_TILT_FLAT: 'Телефон горизонтально',
    PHONE_TILT_VERTICAL: 'Телефон вертикально'
  },
  cn: {
    PHONE_TILT_SCALE: '0°平放 · 90°竖直',
    PHONE_TILT_FLAT: '手机平放（水平）',
    PHONE_TILT_VERTICAL: '手机竖直'
  },
  jp: {
    PHONE_TILT_SCALE: '0°水平 · 90°垂直',
    PHONE_TILT_FLAT: 'スマホ水平',
    PHONE_TILT_VERTICAL: 'スマホ垂直'
  },
  ar: {
    PHONE_TILT_SCALE: '0° أفقي · 90° عمودي',
    PHONE_TILT_FLAT: 'الهاتف أفقي',
    PHONE_TILT_VERTICAL: 'الهاتف عمودي'
  },
  he: {
    PHONE_TILT_SCALE: '0° אופקי · 90° אנכי',
    PHONE_TILT_FLAT: 'טלפון אופקי',
    PHONE_TILT_VERTICAL: 'טלפון אנכי'
  },
  el: {
    PHONE_TILT_SCALE: '0° οριζόντια · 90° κατακόρυφα',
    PHONE_TILT_FLAT: 'Τηλέφωνο οριζόντια',
    PHONE_TILT_VERTICAL: 'Τηλέφωνο κατακόρυφα'
  },
  in: {
    PHONE_TILT_SCALE: '0° datar · 90° tegak',
    PHONE_TILT_FLAT: 'Ponsel mendatar',
    PHONE_TILT_VERTICAL: 'Ponsel tegak'
  }
};

for (const [lang, add] of Object.entries(keys)) {
  const file = path.join(dir, `${lang}.json`);
  const j = JSON.parse(fs.readFileSync(file, 'utf8'));
  const ac = j.ASTRO_COMPASS;
  if (!ac) {
    console.error('missing ASTRO_COMPASS', lang);
    continue;
  }
  Object.assign(ac, add);
  fs.writeFileSync(file, JSON.stringify(j, null, 2) + '\n');
  console.log('ok', lang);
}
